test_rows = test_input_str.strip().split('\n')

def transform(grid):
    rows = grid
    n, m = len(rows), len(rows[0])

    # Convert to 2D list of ints
    grid_ints = [[int(rows[r][c]) for c in range(m)] for r in range(n)]

    out = [[0] * m for _ in range(n)]

    # 1. Mark boundaries (6s) stay as 6s
    for r in range(n):
        for c in range(m):
            if grid_ints[r][c] == 6:
                out[r][c] = 6
            # Convert all 9s to 4s
            elif grid_ints[r][c] == 9:
                out[r][c] = 4

    # 2. Fill region as parallelogram
    # At row 0: fill from col 9 to 17
    # At row 19: fill from col 0 to 8
    # Formula: left = 9 - 9r/19, right = 17 - 9r/19
    for r in range(n):
        left_col = 9 - (9 * r) // 19
        right_col = 17 - (9 * r) // 19
        for c in range(left_col, right_col + 1):
            if 0 <= c < m:
                if out[r][c] == 0:
                    out[r][c] = 9

    # 3. Restore background (0 -> 5)
    for r in range(n):
        for c in range(m):
            if out[r][c] == 0:
                out[r][c] = 5

    return out

r_out = transform(test_rows)
print(f"Output: {len(r_out)}x{len(r_out[0])}")

# Print full output
for r in range(20):
    print(' '.join(map(str, r_out[r])))

